/**
 * Animated previews of the `xfade` transitions: one sprite sheet generated by
 * `scripts/generate-transition-previews.mjs` into `assets/transition-previews.webp`,
 * holding a cell per transition in catalogue order, row by row.
 */

import transitionCatalogue from '../../../../../assets/transitions.json'
import previewSpriteUrl from '../../../../../assets/transition-previews.webp?url'
import { XFADE_TRANSITIONS } from '@/lib/video-program/transition-catalog'

const { columns } = transitionCatalogue.preview
const rows = Math.ceil(XFADE_TRANSITIONS.length / columns)

function axisPercent(cell, cells) {
  return cells > 1 ? (cell / (cells - 1)) * 100 : 0
}

/**
 * Returns the style that shows a transition's animated preview on an element with the aspect ratio of a preview cell.
 * @param {string} type `xfade` transition name.
 * @returns {{backgroundImage: string, backgroundSize: string, backgroundPosition: string}} Inline style.
 */
export function transitionPreviewStyle(type) {
  const index = XFADE_TRANSITIONS.indexOf(type)
  if (index === -1) throw new Error(`Transition ${type} has no preview`)
  return {
    backgroundImage: `url(${previewSpriteUrl})`,
    backgroundSize: `${columns * 100}% ${rows * 100}%`,
    backgroundPosition: `${axisPercent(index % columns, columns)}% ${axisPercent(Math.floor(index / columns), rows)}%`,
  }
}
